CREATE TABLE dbo.T (Id int NOT NULL CONSTRAINT PK_T PRIMARY KEY, A int NULL)
GO
CREATE VIEW dbo.V AS SELECT Id, A FROM dbo.T
GO
CREATE PROCEDURE dbo.P @x int AS SELECT Id FROM dbo.T WHERE Id = @x
GO
CREATE FUNCTION dbo.F (@x int) RETURNS int AS BEGIN RETURN @x END
GO
CREATE FUNCTION dbo.FI (@x int) RETURNS TABLE AS RETURN SELECT Id, A FROM dbo.T WHERE A = @x
GO
CREATE FUNCTION dbo.FM (@x int) RETURNS @r TABLE (Id int) AS BEGIN INSERT @r SELECT Id FROM dbo.T RETURN END
GO
CREATE PROCEDURE dbo.OnlyIn2 AS SELECT 2
